    "UITexasRule_title111": "\u904E\u838A",
    "UITexasRule_detail1": "\u9700\u8981\u7B49\u5230\u81EA\u5DF1\u662F\u5927\u76F2\u4F4D\u6642\uFF0C\u624D\u80FD\u52A0\u5165\u724C\u5C40",
    "UITexasRule_title112": "\u88DC\u76F2",
    "UITexasRule_detail2": "\u4E0B\u4E00\u624B\u6642\uFF0C\u73A9\u5BB6\u82E5\u4E0D\u662F\u5927\u5C0F\u76F2\u4F4D\uFF0C\u5C07\u5728\u6263\u9664\u5927\u76F2\u6578\u984D\u7684UC\u5F8C\uFF0C\u7ACB\u5373\u52A0\u5165\u724C\u5C40\u56DE\u5408\u3002\u5C0F\u76F2\u4F4D\u73A9\u5BB6\u5C07\u5728\u6263\u81F3\u5927\u76F2\u6578\u984D\u7684UC\u5F8C\uFF0C\u7ACB\u5373\u52A0\u5165\u724C\u5C40\u56DE\u5408\u3002\u5927\u76F2\u4F4D\u73A9\u5BB6\u5C07\u76F4\u63A5\u52A0\u5165\u724C\u5C40\u56DE\u5408\u3002",
    "UITexasRule_title113": "\u6700\u77ED\u4E0A\u684C\u6642\u9593",
    "UITexasRule_detail3": "\u7576\u7BA1\u7406\u54E1\u958B\u555F\u6700\u77ED\u6253\u724C\u6642\u9593\uFF0C\u73A9\u5BB6\u5728\u724C\u5C40\u5167\u6253\u724C\u6642\u9593\u5FC5\u9808\u6EFF\u8DB3\u8A72\u6700\u77ED\u6642\u9593\uFF0C\u5426\u5247\u7CFB\u7D71\u5C07\u5BE6\u884C\u7559\u76F2\u4EE3\u6253\u7684\u8A17\u7BA1\u6A21\u5F0F\u3002",
    "UITexasRule_detail4": "1.\u7576\u5168\u90E8\u73A9\u5BB6All in\u5F8C\u555F\u52D5\u4FDD\u96AA",
    "UITexasRule_detail5": "2.\u7531\u7576\u524D\u724C\u578B\u6700\u5927\u73A9\u5BB6\u9032\u884C\u8CFC\u8CB7,\u82E5\u51FA\u73FE\u591A\u500B\u5E95\u6C60\u5247\u7531\u6700\u5927\u5E95\u6C60\u4E2D\u9818\u5148\u7684\u73A9\u5BB6\u8CFC\u8CB7\uFF0C\u4E14\u53EA\u80FD\u8CFC\u8CB7\u6700\u5927\u5E95\u6C60",
    "UITexasRule_detail6": "3.\u7576\u4FDD\u96AA\u6D89\u53CA\u7684\u5E95\u6C60\u4E2D\u8D85\u904E3\u500B\u73A9\u5BB6\u7684\u6642\u5019,\u4FDD\u96AA\u4E0D\u555F\u52D5\uFF082\u4EBA\u6216\u80053\u4EBA\u6642\u53EF\u4EE5\u8CB7\u4FDD\u96AA\uFF09\u3002",
    "UITexasRule_detail7": "4.\u7FFB\u724C\u4E09\u5F35\u4E0D\u53EF\u8CFC\u8CB7\u4FDD\u96AA,\u8F49\u724C\u6295\u4FDD\u984D\u4E0D\u5F97\u8D85\u904E0.25*\u5E95\u6C60\uFF0C\u6CB3\u724C\u6295\u4FDD\u984D\u4E0D\u5F97\u8D85\u904E0.5*\u5E95\u6C60",
    "UITexasRule_detail8": "5.\u5982\u679C\u8CFC\u8CB7\u4E86\u8F49\u724C\u4FDD\u96AA,\u7CFB\u7D71\u6703\u5F37\u5236\u73A9\u5BB6\u8CFC\u8CB7\u6CB3\u724C\u5C11\u91CF\u4FDD\u96AA,\u80CC\u56DE\u8F49\u724C\u7684\u4FDD\u96AA\u6295\u5165",
    "UITexasRule_detail9": "5.\u82E5\u8F49\u724C\u8CFC\u8CB7\u4FDD\u96AA\u672A\u4E2D,\u5247\u6CB3\u724C\u5FC5\u9808\u8CFC\u8CB7\u6240\u6709\u88DC\u724C,\u4E14\u6CB3\u724C\u7684\u8CE0\u4ED8\u984D\u5FC5\u9808\u5927\u65BC\u8F49\u724C\u7684\u6295\u4FDD\u984D",
    "UITexasRule_detail10": "6.\u82E5\u73A9\u5BB6\u53EA\u8CFC\u8CB7\u90E8\u5206\u88DC\u724C,\u7CFB\u7D71\u70BA\u898F\u907F\u73A9\u5BB6\u88ABBB\u7684\u98A8\u96AA,\u6703\u81EA\u52D5\u8CFC\u8CB7\u5269\u9918\u88DC\u724C,\u5E36\u56DE\u73A9\u5BB6\u7684\u6295\u4FDD\u984D",
    "UITexasRule_detail11": "7.\u724C\u5167[\u5BE6\u6642\u6230\u7E3E][\u724C\u8B5C]\u548C\u751F\u6DAF\u4E2D[\u6230\u7E3E\u8A73\u60C5]\u4E2D\u986F\u793A\u4FDD\u96AA\u6578\u64DA",
    "UITexasRule_detail12": "8.\u5FB7\u5DDE\uFF0C\u5967\u99AC\u54C8\u7684outs\u8D85\u904E30\u5F35\uFF0C\u77ED\u724C\u7684OUTS\u8D85\u904E19\u5F35\u6642\uFF0C\u4FDD\u96AA\u4E0D\u6FC0\u6D3B\u3002",
    "UITexasRule_detail13": "9.\u82E5\u7576\u591A\u4EBA\u63A8All-in\uFF0C\u51FA\u73FE\u591A\u5E95\u6C60\u7684\u60C5\u6CC1\u4E0B\uFF0C\u9818\u5148\u73A9\u5BB6\u53EA\u80FD\u8CFC\u8CB7\u81EA\u8EAB\u53C3\u8207\u7684\u6700\u5927\u7A4D\u5206\u7684\u5E95\u6C60\u7684Outs\uFF0C\u7121\u6CD5\u8CFC\u8CB7\u6240\u6709\u5E95\u6C60\u7684Outs\u3002",
    "UITexasRule_title114": "\u64CD\u4F5C",
    "UITexasRule_detail15": "1.\u4FDD\u672C\uFF1A\u8CE0\u4ED8\u984D=\u73A9\u5BB6\u6295\u5165",
    "UITexasRule_detail16": "2.\u6EFF\u6C60\uFF1A\u4E0D\u7BA1\u4FDD\u96AA\u4E2D\u6C92\u4E2D, \u6536\u76CA\u76F8\u7B49",
    "UITexasRule_detail17": "3.\u8CFC\u8CB7\u4FDD\u96AA\u6D88\u8017\u7684UC\u5F9E\u5E95\u6C60\u4E2D\u6263\u9664",
    "UITexasRule_detail18": "4.\u82E5\u8CB7\u4E2D,\u7CFB\u7D71\u6839\u64DA\u8CE0\u7387\u76F4\u63A5\u8CE0\u4ED8\u7D66\u73A9\u5BB6",
