    "Mahjong_StandardRuleContent20_3": "\u3010\u6436\u6760\u80E1\u3011x8\uFF0C\u80E1\u5176\u5B83\u4EBA\u88DC\u6760\u7684\u90A3\u5F35\u724C\uFF0C\u70BA\u6436\u6760\u80E1\u3002 \u88AB\u6436\u6760\u7684\u6760\u724C\u4E0D\u7B97\u6760\uFF1B",
    "Mahjong_StandardRuleContent20_4": "\u3010\u6760\u4E0A\u82B1\u3011x8\uFF0C\u6760\u5F8C\u6478\u5230\u7684\u724C\u81EA\u6A21\u80E1\u724C\uFF08\u6760\u4E86\u4E4B\u5F8C\u88DC\u724C\u800C\u80E1\uFF09\uFF1B",
    "Mahjong_StandardRuleContent20_5": "\u3010\u9580\u6E05\u3011x4\uFF0C\u6C92\u6709\u5403\u3001\u78B0\u3001\u660E\u6760\uFF0C\u6700\u7D42\u81EA\u6478\u3001\u9EDE\u70AE\u7B49\u7BA1\u9053\u80E1\u724C\u3002\u6697\u6746\u6254\u7B97\u9580\u6E05\uFF1B",
    "Mahjong_StandardRuleContent20_6": "\u3010\u786C\u80E1\u3011x2\uFF0C\u80E1\u724C\u6642\uFF0C\u624B\u4E2D\u6C92\u6709\u8CF4\u5B50\u724C\uFF1B",
    "Mahjong_StandardRuleContent20_7": "\u3010\u81EA\u6478\u3011x2\uFF0C\u81EA\u6478\u80E1\u724C",
    "UICreateRoomOptions5": "\u904E\u76F2",
    "Mahjong_BloodRiverRuleTitle1": "\u5E36\u201C\u7D05\u4E2D\u201D\u73A9\u6CD5\uFF08\u53EF\u9078\uFF09",
    "Mahjong_BloodRiverRuleContent1_1": "\u201C\u7D05\u4E2D\u8840\u6D41\u201D\u662F\u5728\u201C\u8840\u6D41\u6210\u6CB3\u201D\u73A9\u6CD5\u898F\u5247\u4E4B\u4E2D\u4E00\u500B\u9078\u64C7\u9805\uFF0C\u9078\u64C7\u5E36\u201C\u7D05\u4E2D\u201D\u73A9\u6CD5\u6703\u591A\u51FA4\u30016\u30018\u5F35\u201C\u4E2D\u201D\u7684\u724C\uFF0C\u5728\u73A9\u6CD5\u4E2D\uFF0C\u7D05\u4E2D\u70BA\u201C\u8CF4\u5B50\u201D\uFF0C\u5C31\u662F\u842C\u80FD\u724C\uFF0C\u53EF\u4EE5\u4EE3\u66FF\u4EFB\u4F55\u724C\u96A8\u610F\u642D\u914D\u4F7F\u7528\uFF1B",
    "Mahjong_BloodRiverRuleContent1_2": "\u201C\u7D05\u4E2D\u201D\u4E0D\u80FD\u55AE\u7368\u4F5C\u70BA\u4E00\u5C0D\u5C07\u724C\u4F86\u55AE\u91E3\u80E1\u724C\uFF1B",
    "Mahjong_BloodRiverRuleContent1_3": "\u201C\u7D05\u4E2D\u201D\u4E0D\u80FD\u55AE\u7368\u7D44\u6210\u523B\u5B57\u548C\u9806\u5B50\uFF1B",
    "Mahjong_BloodRiverRuleContent1_4": "\u201C\u7D05\u4E2D\u201D\u53EF\u4EE5\u4F5C\u70BA\u5269\u4E0B\u6700\u5F8C\u4E00\u5F35\u724C\u55AE\u91E3\u80E1\u724C\uFF0C\u53EA\u80FD\u80E1\u201C\u7D05\u4E2D\u201D\uFF0C\u8A08\u201C\u7D05\u4E2D\u91D1\u9264\u9264\u201D\u724C\u578B\uFF0C\u8543x16\uFF1B",
    "Mahjong_BloodRiverRuleContent2_1": "\u4F7F\u7528\u4E0D\u5305\u542B\u5B57\u724C\uFF08\u5373\u6C92\u6709\u6771\u3001\u5357\u3001\u897F\u3001\u5317\u3001\u4E2D\u3001\u767C\u3001\u767D\uFF09\u7684108\u5F35\u724C\uFF0C\u53EA\u5305\u62EC1-9\u842C\u30011-9\u7B52\u30011-9\u689D\u4E09\u8272\u5E8F\u6578\u724C\u540436\u5F35",
    "Mahjong_BloodRiverRuleTitle5": "\u80E1\u724C\u52A0\u500D\uFF08\u53EF\u9078\uFF09",
    "Mahjong_BloodRiverRuleContent5_1": "\u6BCF\u5C40\u904A\u6232\u4E2D\uFF0C\u6BCF\u6B21\u80E1\u724C\u984D\u5916\uFF08\u73A9\u5BB6\u80E1\u724C\u6B21\u6578-1\uFF09x5\u500D\u3002\u5982\u73A9\u5BB6\u7B2C\u4E00\u6B21\u80E1\u724C\u70BA\u6B63\u5E38\u500D\u6578\uFF0C\u7B2C\u4E8C\u6B21\u70BA\u6B63\u5E38\u500D\u6578+5\uFF0C\u7B2C\u4E09\u6B21\u70BA\u6B63\u5E38\u500D\u6578+10\u500D",
    "Mahjong_BloodRiverRuleTitle7": "\u4F86\u96FB\u8F49\u63A5\uFF08\u53EF\u9078\uFF09",
