    "Mahjong_StandardRuleTitle5": "\u8D56\u5B50\uFF08\u4E07\u80FD\u724C\uFF09\uFF08\u53EF\u9009\uFF09",
    "Mahjong_StandardRuleTitle5_1": "1.\u4E09\u9009\u4E00",
    "Mahjong_StandardRuleContent5_1": "\u6BCF\u5C40\u5F00\u59CB\u524D\u7FFB\u51FA\u4E00\u5F20\u724C\uFF0C\u8FD9\u5F20\u724C\u7684\u70B9\u6570+1\u5373\u4E3A\u672C\u5C40\u7684\u8D56\u5B50\u724C\u3002\u5982\u7FFB\u724C\u51FA5\u4E07\uFF0C\u5219\u516D\u4E07\u4E3A\u8D56\u5B50\uFF1B",
