    "UICreateRoomOptions5": "\u8FC7\u76F2",
    "Mahjong_BloodRiverRuleTitle1": "\u5E26\u201C\u7EA2\u4E2D\u201D\u73A9\u6CD5\uFF08\u53EF\u9009\uFF09",
    "Mahjong_BloodRiverRuleContent1_1": "\u201C\u7EA2\u4E2D\u8840\u6D41\u201D\u662F\u5728\u201C\u8840\u6D41\u6210\u6CB3\u201D\u73A9\u6CD5\u89C4\u5219\u4E4B\u4E2D\u4E00\u4E2A\u9009\u62E9\u9879\uFF0C\u9009\u62E9\u5E26\u201C\u7EA2\u4E2D\u201D\u73A9\u6CD5\u4F1A\u591A\u51FA4\u30016\u30018\u5F20\u201C\u4E2D\u201D\u7684\u724C\uFF0C\u5728\u73A9\u6CD5\u4E2D\uFF0C\u7EA2\u4E2D\u4E3A\u201C\u8D56\u5B50\u201D\uFF0C\u5C31\u662F\u4E07\u80FD\u724C\uFF0C\u53EF\u4EE5\u4EE3\u66FF\u4EFB\u4F55\u724C\u968F\u610F\u642D\u914D\u4F7F\u7528\uFF1B",
    "Mahjong_BloodRiverRuleContent1_2": "\u201C\u7EA2\u4E2D\u201D\u4E0D\u80FD\u5355\u72EC\u4F5C\u4E3A\u4E00\u5BF9\u5C06\u724C\u6765\u5355\u9493\u80E1\u724C\uFF1B",
    "Mahjong_BloodRiverRuleContent1_3": "\u201C\u7EA2\u4E2D\u201D\u4E0D\u80FD\u5355\u72EC\u7EC4\u6210\u523B\u5B57\u548C\u987A\u5B50\uFF1B",
    "Mahjong_BloodRiverRuleContent1_4": "\u201C\u7EA2\u4E2D\u201D\u53EF\u4EE5\u4F5C\u4E3A\u5269\u4E0B\u6700\u540E\u4E00\u5F20\u724C\u5355\u9493\u80E1\u724C\uFF0C\u53EA\u80FD\u80E1\u201C\u7EA2\u4E2D\u201D\uFF0C\u8BA1\u201C\u7EA2\u4E2D\u91D1\u94A9\u94A9\u201D\u724C\u578B\uFF0C\u8543x16\uFF1B",
    "Mahjong_BloodRiverRuleContent2_1": "\u4F7F\u7528\u4E0D\u5305\u542B\u5B57\u724C\uFF08\u5373\u6CA1\u6709\u4E1C\u3001\u5357\u3001\u897F\u3001\u5317\u3001\u4E2D\u3001\u53D1\u3001\u767D\uFF09\u7684108\u5F20\u724C\uFF0C\u53EA\u5305\u62EC1-9\u4E07\u30011-9\u7B52\u30011-9\u6761\u4E09\u8272\u5E8F\u6570\u724C\u540436\u5F20",
    "Mahjong_BloodRiverRuleTitle5": "\u80E1\u724C\u52A0\u500D\uFF08\u53EF\u9009\uFF09",
    "Mahjong_BloodRiverRuleContent5_1": "\u6BCF\u5C40\u6E38\u620F\u4E2D\uFF0C\u6BCF\u6B21\u80E1\u724C\u989D\u5916\uFF08\u73A9\u5BB6\u80E1\u724C\u6B21\u6570-1\uFF09x5\u500D\u3002\u5982\u73A9\u5BB6\u7B2C\u4E00\u6B21\u80E1\u724C\u4E3A\u6B63\u5E38\u500D\u6570\uFF0C\u7B2C\u4E8C\u6B21\u4E3A\u6B63\u5E38\u500D\u6570+5\uFF0C\u7B2C\u4E09\u6B21\u4E3A\u6B63\u5E38\u500D\u6570+10\u500D",
    "Mahjong_BloodRiverRuleTitle7": "\u547C\u53EB\u8F6C\u79FB\uFF08\u53EF\u9009\uFF09",
    "Mahjong_BloodRiverRuleContent7_1": "\u73A9\u5BB6\u6760\u4E0A\u70AE\uFF0C\u9700\u8981\u5C06\u6760\u724C\u6240\u8D62\u7684\u6536\u76CA\u8F6C\u7ED9\u80E1\u724C\u7684\u73A9\u5BB6\uFF1B",
