    "UIEgg_HeadRateTips": "\u72EC\u7ACB\uFF0C\u6240\u6709\u7684\u624B\u6570\u4E2D\uFF0C\u83B7\u5F97\u5934\u6E38\u7684\u6BD4\u4F8B",
